    | (FStarC_Syntax_Syntax.U_unif (u__1, u__2, u__3)) when ((cfg).FStarC_TypeChecker_Cfg.steps).FStarC_TypeChecker_Cfg.check_no_uvars -> (let tmp = (FStarC_Range_Ops.string_of_range (FStarC_TypeChecker_Env.get_range (cfg).FStarC_TypeChecker_Cfg.tcenv)) in
