let norm_universe (cfg : FStarC_TypeChecker_Cfg.cfg) (env : (((FStarC_Syntax_Syntax.binder) option * closure * (((FStarC_Syntax_Syntax.subst_elt) list) option ref))) list) (u : FStarC_Syntax_Syntax.universe) : FStarC_Syntax_Syntax.universe =
  (let norm_univs_for_max = (fun us -> (let us1 = (FStarC_Util.sort_with FStarC_Syntax_Util.compare_univs us) in
    let tmp = (FStarC_List.fold_left (fun tmp u1 -> (match tmp with
        | (cur_kernel, cur_max, out) -> (let tmp1 = (FStarC_Syntax_Util.univ_kernel u1) in
          (match tmp1 with
            | (k_u, n) -> (let tmp2 = (FStarC_Syntax_Util.eq_univs cur_kernel k_u) in
              (if tmp2 then (cur_kernel, u1, out) else (k_u, u1, (cur_max :: out))))
          ))
      )) (FStarC_Syntax_Syntax.U_zero, FStarC_Syntax_Syntax.U_zero, []) us1) in
    (match tmp with
      | (tmp1, u1, out) -> (FStarC_List.rev (u1 :: out))
    ))) in
  (if ((cfg).FStarC_TypeChecker_Cfg.steps).FStarC_TypeChecker_Cfg.erase_universes then FStarC_Syntax_Syntax.U_unknown else (let tmp = ((norm_universe__aux cfg env norm_univs_for_max) u) in
  (match tmp with
    | [] -> FStarC_Syntax_Syntax.U_zero
    | (FStarC_Syntax_Syntax.U_zero :: []) -> FStarC_Syntax_Syntax.U_zero
    | (FStarC_Syntax_Syntax.U_zero :: (u1 :: [])) -> u1
    | (FStarC_Syntax_Syntax.U_zero :: us) -> (FStarC_Syntax_Syntax.U_max (us))
    | (u1 :: []) -> u1
    | us -> (FStarC_Syntax_Syntax.U_max (us))
  ))))

let rec do_rebuild__norm_pat (cfg : FStarC_TypeChecker_Cfg.cfg) (norm_or_whnf : ((((FStarC_Syntax_Syntax.binder) option * closure * (((FStarC_Syntax_Syntax.subst_elt) list) option ref))) list -> ((FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax -> (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax))) (env : (((FStarC_Syntax_Syntax.binder) option * closure * (((FStarC_Syntax_Syntax.subst_elt) list) option ref))) list) (p : (FStarC_Syntax_Syntax.pat') FStarC_Syntax_Syntax.withinfo_t) : ((FStarC_Syntax_Syntax.pat') FStarC_Syntax_Syntax.withinfo_t * (((FStarC_Syntax_Syntax.binder) option * closure * (((FStarC_Syntax_Syntax.subst_elt) list) option ref))) list) =
  (match (p).FStarC_Syntax_Syntax.v with
    | (FStarC_Syntax_Syntax.Pat_constant (tmp)) -> (p, env)
    | (FStarC_Syntax_Syntax.Pat_cons (fv, us_opt, pats)) -> (let us_opt1 = (if ((cfg).FStarC_TypeChecker_Cfg.steps).FStarC_TypeChecker_Cfg.erase_universes then None else (match us_opt with
          | None -> None
          | (Some (us)) -> (let tmp = (FStarC_List.map (norm_universe cfg env) us) in
            (Some (tmp)))
        )) in
      let tmp = (FStarC_List.fold_left (fun tmp tmp1 -> (match (tmp, tmp1) with
          | ((pats1, env1), (p1, b)) -> (let tmp2 = ((do_rebuild__norm_pat cfg norm_or_whnf) env1 p1) in
            (match tmp2 with
              | (p2, env2) -> (((p2, b) :: pats1), env2)
            ))
        )) ([], env) pats) in
      (match tmp with
        | (pats1, env1) -> ({ FStarC_Syntax_Syntax.v = (FStarC_Syntax_Syntax.Pat_cons (fv, us_opt1, (FStarC_List.rev pats1)));
            p = (p).FStarC_Syntax_Syntax.p }, env1)
      ))
    | (FStarC_Syntax_Syntax.Pat_var (x)) -> (let tmp = (norm_or_whnf env (x).FStarC_Syntax_Syntax.sort) in
      let x1 = { FStarC_Syntax_Syntax.ppname = (x).FStarC_Syntax_Syntax.ppname;
          index = (x).FStarC_Syntax_Syntax.index;
          sort = tmp } in
      let tmp1 = (dummy ()) in
      let tmp2 = (tmp1 :: env) in
      ({ FStarC_Syntax_Syntax.v = (FStarC_Syntax_Syntax.Pat_var (x1));
        p = (p).FStarC_Syntax_Syntax.p }, tmp2))
    | (FStarC_Syntax_Syntax.Pat_dot_term (eopt)) -> (let eopt1 = (FStarC_Option.map (norm_or_whnf env) eopt) in
      ({ FStarC_Syntax_Syntax.v = (FStarC_Syntax_Syntax.Pat_dot_term (eopt1));
        p = (p).FStarC_Syntax_Syntax.p }, env))
  )

let rec maybe_weakly_reduced (tm : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) : bool =
  (let aux_comp = (fun c -> (let ct = (c).FStarC_Syntax_Syntax.n in
    (maybe_weakly_reduced (ct).FStarC_Syntax_Syntax.result_typ))) in
  let t = (FStarC_Syntax_Subst.compress tm) in
  (match (t).FStarC_Syntax_Syntax.n with
    | (FStarC_Syntax_Syntax.Tm_delayed (tmp)) -> (FStarC_Effect.failwith "Impossible")
    | (FStarC_Syntax_Syntax.Tm_name (tmp)) -> false
    | (FStarC_Syntax_Syntax.Tm_uvar (u__1, u__2)) -> false
    | (FStarC_Syntax_Syntax.Tm_type (tmp)) -> false
    | (FStarC_Syntax_Syntax.Tm_bvar (tmp)) -> false
    | (FStarC_Syntax_Syntax.Tm_fvar (tmp)) -> false
    | (FStarC_Syntax_Syntax.Tm_constant (tmp)) -> false
    | (FStarC_Syntax_Syntax.Tm_lazy (tmp)) -> false
    | FStarC_Syntax_Syntax.Tm_unknown -> false
    | (FStarC_Syntax_Syntax.Tm_uinst (u__1, u__2)) -> false
    | (FStarC_Syntax_Syntax.Tm_quoted (u__1, u__2)) -> false
    | (FStarC_Syntax_Syntax.Tm_let (tmp)) -> true
    | (FStarC_Syntax_Syntax.Tm_abs (tmp)) -> true
    | (FStarC_Syntax_Syntax.Tm_arrow (tmp)) -> true
    | (FStarC_Syntax_Syntax.Tm_refine (tmp)) -> true
    | (FStarC_Syntax_Syntax.Tm_match (tmp)) -> true
    | (FStarC_Syntax_Syntax.Tm_app (tmp)) -> (let tmp1 = (FStarC_Syntax_Util.head_and_args_full t) in
      (match tmp1 with
        | (hd, args) -> (let tmp2 = (maybe_weakly_reduced hd) in
          (if tmp2 then true else (FStarC_Util.for_some (fun tmp3 -> (match tmp3 with
            | (a, tmp4) -> (maybe_weakly_reduced a)
          )) args)))
      ))
    | (FStarC_Syntax_Syntax.Tm_ascribed ({ FStarC_Syntax_Syntax.tm = t1; asc = u__1; asc1 = u__2; asc2 = u__3; eff_opt = tmp; _ })) -> (let tmp1 = (maybe_weakly_reduced t1) in
      (if tmp1 then true else (let tmp2 = (u__1, u__2, u__3) in
      (match tmp2 with
        | (asc_tc, asc_tac, tmp3) -> (let tmp4 = (match asc_tc with
              | (FStar_Pervasives.Inl (t2)) -> (maybe_weakly_reduced t2)
              | (FStar_Pervasives.Inr (c2)) -> (aux_comp c2)
            ) in
          (if tmp4 then true else (match asc_tac with
            | None -> false
            | (Some (tac)) -> (maybe_weakly_reduced tac)
          )))
      ))))
    | (FStarC_Syntax_Syntax.Tm_meta ({ FStarC_Syntax_Syntax.tm = t1; meta = m; _ })) -> (let tmp = (maybe_weakly_reduced t1) in
      (if tmp then true else (match m with
        | (FStarC_Syntax_Syntax.Meta_pattern (tmp1, args)) -> (FStarC_Util.for_some (FStarC_Util.for_some (fun tmp2 -> (match tmp2 with
            | (a, tmp3) -> (maybe_weakly_reduced a)
          ))) args)
        | (FStarC_Syntax_Syntax.Meta_monadic_lift (tmp1, tmp2, t')) -> (maybe_weakly_reduced t')
        | (FStarC_Syntax_Syntax.Meta_monadic (tmp1, t')) -> (maybe_weakly_reduced t')
        | (FStarC_Syntax_Syntax.Meta_labeled (u__1, u__2, u__3)) -> false
        | (FStarC_Syntax_Syntax.Meta_desugared (tmp1)) -> false
        | (FStarC_Syntax_Syntax.Meta_named (tmp1)) -> false
      )))
  ))

let rec do_rebuild__is_cons (head : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) : bool =
  (let tmp = (FStarC_Syntax_Subst.compress head) in
  let tmp1 = (tmp).FStarC_Syntax_Syntax.n in
  (match tmp1 with
    | (FStarC_Syntax_Syntax.Tm_uinst (h, tmp2)) -> (do_rebuild__is_cons h)
    | (FStarC_Syntax_Syntax.Tm_constant (tmp2)) -> true
    | (FStarC_Syntax_Syntax.Tm_fvar ({ FStarC_Syntax_Syntax.fv_name = tmp2; fv_qual = (Some (FStarC_Syntax_Syntax.Data_ctor)); _ })) -> true
    | (FStarC_Syntax_Syntax.Tm_fvar ({ FStarC_Syntax_Syntax.fv_name = tmp2; fv_qual = (Some ((FStarC_Syntax_Syntax.Record_ctor (u__1, u__2)))); _ })) -> true
    | tmp2 -> false
  ))

let rec do_rebuild__matches_pat (scrutinee_orig : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) (p : (FStarC_Syntax_Syntax.pat') FStarC_Syntax_Syntax.withinfo_t) : (((FStarC_Syntax_Syntax.bv * (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax)) list, bool) FStar_Pervasives.either =
  (let scrutinee = (FStarC_Syntax_Util.unmeta scrutinee_orig) in
  let scrutinee1 = (FStarC_Syntax_Util.unlazy scrutinee) in
  let tmp = (FStarC_Syntax_Util.head_and_args_full scrutinee1) in
  (match tmp with
    | (head, args) -> (match (p).FStarC_Syntax_Syntax.v with
        | (FStarC_Syntax_Syntax.Pat_var (bv)) -> (FStar_Pervasives.Inl (((bv, scrutinee_orig) :: [])))
        | (FStarC_Syntax_Syntax.Pat_dot_term (tmp1)) -> (FStar_Pervasives.Inl ([]))
        | (FStarC_Syntax_Syntax.Pat_constant (s)) -> (match (scrutinee1).FStarC_Syntax_Syntax.n with
            | (FStarC_Syntax_Syntax.Tm_constant (s')) when (FStarC_Const.eq_const s s') -> (FStar_Pervasives.Inl ([]))
            | tmp1 -> (let tmp2 = (do_rebuild__is_cons head) in
              let tmp3 = (not tmp2) in
              (FStar_Pervasives.Inr (tmp3)))
          )
        | (FStarC_Syntax_Syntax.Pat_cons (fv, tmp1, arg_pats)) -> (let tmp2 = (FStarC_Syntax_Util.un_uinst head) in
          let tmp3 = (tmp2).FStarC_Syntax_Syntax.n in
          (match tmp3 with
            | (FStarC_Syntax_Syntax.Tm_fvar (fv')) when (FStarC_Syntax_Syntax.fv_eq fv fv') -> (do_rebuild__matches_args [] args arg_pats)
            | tmp4 -> (let tmp5 = (do_rebuild__is_cons head) in
              let tmp6 = (not tmp5) in
              (FStar_Pervasives.Inr (tmp6)))
          ))
      )
  ))

and do_rebuild__matches_args (out : ((FStarC_Syntax_Syntax.bv * (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax)) list) (a : (((FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax * (FStarC_Syntax_Syntax.arg_qualifier) option)) list) (p : (((FStarC_Syntax_Syntax.pat') FStarC_Syntax_Syntax.withinfo_t * bool)) list) : (((FStarC_Syntax_Syntax.bv * (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax)) list, bool) FStar_Pervasives.either =
  (match (a, p) with
    | ([], []) -> (FStar_Pervasives.Inl (out))
    | (((t, tmp) :: rest_a), ((p1, tmp1) :: rest_p)) -> (let tmp2 = (do_rebuild__matches_pat t p1) in
      (match tmp2 with
        | (FStar_Pervasives.Inl (s)) -> (do_rebuild__matches_args (FStarC_List.op_At out s) rest_a rest_p)
        | m -> m
      ))
    | tmp -> (FStar_Pervasives.Inr (false))
  )

let weak_cfg_cache : (((FStarC_TypeChecker_Cfg.cfg * FStarC_TypeChecker_Cfg.cfg)) option ref) =
  (ref None)

let weak_cfg (cfg : FStarC_TypeChecker_Cfg.cfg) : FStarC_TypeChecker_Cfg.cfg =
  (if ((cfg).FStarC_TypeChecker_Cfg.steps).FStarC_TypeChecker_Cfg.weak then cfg else (let tmp = (!(weak_cfg_cache)) in
  (match tmp with
    | (Some ((cfg0, cfg0'))) when (FStarC_Util.physical_equality cfg cfg0) -> cfg0'
    | tmp1 -> (let cfg' = { FStarC_TypeChecker_Cfg.steps = (let tmp2 = (cfg).FStarC_TypeChecker_Cfg.steps in
          { FStarC_TypeChecker_Cfg.beta = (tmp2).FStarC_TypeChecker_Cfg.beta;
            iota = (tmp2).FStarC_TypeChecker_Cfg.iota;
            zeta = (tmp2).FStarC_TypeChecker_Cfg.zeta;
            zeta_full = (tmp2).FStarC_TypeChecker_Cfg.zeta_full;
            weak = true;
            hnf = (tmp2).FStarC_TypeChecker_Cfg.hnf;
            primops = (tmp2).FStarC_TypeChecker_Cfg.primops;
            unrepresentable_primops = (tmp2).FStarC_TypeChecker_Cfg.unrepresentable_primops;
            do_not_unfold_pure_lets = (tmp2).FStarC_TypeChecker_Cfg.do_not_unfold_pure_lets;
            unfold_until = (tmp2).FStarC_TypeChecker_Cfg.unfold_until;
            unfold_only = (tmp2).FStarC_TypeChecker_Cfg.unfold_only;
            unfold_once = (tmp2).FStarC_TypeChecker_Cfg.unfold_once;
            unfold_fully = (tmp2).FStarC_TypeChecker_Cfg.unfold_fully;
            unfold_attr = (tmp2).FStarC_TypeChecker_Cfg.unfold_attr;
            unfold_qual = (tmp2).FStarC_TypeChecker_Cfg.unfold_qual;
            unfold_namespace = (tmp2).FStarC_TypeChecker_Cfg.unfold_namespace;
            dont_unfold_attr = (tmp2).FStarC_TypeChecker_Cfg.dont_unfold_attr;
            pure_subterms_within_computations = (tmp2).FStarC_TypeChecker_Cfg.pure_subterms_within_computations;
            simplify = (tmp2).FStarC_TypeChecker_Cfg.simplify;
            erase_universes = (tmp2).FStarC_TypeChecker_Cfg.erase_universes;
            allow_unbound_universes = (tmp2).FStarC_TypeChecker_Cfg.allow_unbound_universes;
            reify_ = (tmp2).FStarC_TypeChecker_Cfg.reify_;
            compress_uvars = (tmp2).FStarC_TypeChecker_Cfg.compress_uvars;
            no_full_norm = (tmp2).FStarC_TypeChecker_Cfg.no_full_norm;
            check_no_uvars = (tmp2).FStarC_TypeChecker_Cfg.check_no_uvars;
            unmeta = (tmp2).FStarC_TypeChecker_Cfg.unmeta;
            unascribe = (tmp2).FStarC_TypeChecker_Cfg.unascribe;
            in_full_norm_request = (tmp2).FStarC_TypeChecker_Cfg.in_full_norm_request;
            weakly_reduce_scrutinee = (tmp2).FStarC_TypeChecker_Cfg.weakly_reduce_scrutinee;
            nbe_step = (tmp2).FStarC_TypeChecker_Cfg.nbe_step;
            for_extraction = (tmp2).FStarC_TypeChecker_Cfg.for_extraction;
            unrefine = (tmp2).FStarC_TypeChecker_Cfg.unrefine;
            default_univs_to_zero = (tmp2).FStarC_TypeChecker_Cfg.default_univs_to_zero;
            tactics = (tmp2).FStarC_TypeChecker_Cfg.tactics;
            reduce_projections = (tmp2).FStarC_TypeChecker_Cfg.reduce_projections });
          tcenv = (cfg).FStarC_TypeChecker_Cfg.tcenv;
          debug = (cfg).FStarC_TypeChecker_Cfg.debug;
          delta_level = (cfg).FStarC_TypeChecker_Cfg.delta_level;
          primitive_steps = (cfg).FStarC_TypeChecker_Cfg.primitive_steps;
          strong = (cfg).FStarC_TypeChecker_Cfg.strong;
          memoize_lazy = (cfg).FStarC_TypeChecker_Cfg.memoize_lazy;
          normalize_pure_lets = (cfg).FStarC_TypeChecker_Cfg.normalize_pure_lets;
          reifying = (cfg).FStarC_TypeChecker_Cfg.reifying;
          compat_memo_ignore_cfg = (cfg).FStarC_TypeChecker_Cfg.compat_memo_ignore_cfg } in
      ((weak_cfg_cache) := (Some ((cfg, cfg'))));
      cfg')
  )))

let disc_proj_info_cached (env : FStarC_TypeChecker_Env.env) (l : FStarC_Ident.lident) : ((FStarC_Syntax_Syntax.qualifier * Prims.int * (Prims.int) option)) option =
  (let k = (FStarC_Ident.string_of_lid l) in
  let tmp = (FStarC_SMap.try_find (env).FStarC_TypeChecker_Env.disc_proj_tab k) in
  (match tmp with
    | (Some (r)) -> r
    | None -> (let r = (FStarC_TypeChecker_Env.disc_proj_info env l) in
      (FStarC_SMap.add (env).FStarC_TypeChecker_Env.disc_proj_tab k r);
      r)
  ))

let disc_proj_head (cfg : FStarC_TypeChecker_Cfg.cfg) (head : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) : ((FStarC_Ident.lident * bool * Prims.int * (Prims.int) option)) option =
  (if (not ((cfg).FStarC_TypeChecker_Cfg.steps).FStarC_TypeChecker_Cfg.iota) then None else (let tmp = (FStarC_Syntax_Util.un_uinst head) in
  let tmp1 = (tmp).FStarC_Syntax_Syntax.n in
  (match tmp1 with
    | (FStarC_Syntax_Syntax.Tm_fvar (h)) -> (let tmp2 = (disc_proj_info_cached (cfg).FStarC_TypeChecker_Cfg.tcenv (h).FStarC_Syntax_Syntax.fv_name) in
      (match tmp2 with
        | None -> None
        | (Some ((q, n_indexed, idx))) -> (match q with
            | (FStarC_Syntax_Syntax.Projector (d, tmp3)) -> (Some ((d, false, n_indexed, idx)))
            | (FStarC_Syntax_Syntax.Discriminator (d)) -> (Some ((d, true, n_indexed, idx)))
            | tmp3 -> (FStarC_Effect.failwith "disc_proj_head: impossible")
          )
      ))
    | tmp2 -> None
  )))

let reduce_disc_proj (cfg : FStarC_TypeChecker_Cfg.cfg) (d : FStarC_Ident.lident) (is_disc : bool) (idx : (Prims.int) option) (scrutinee : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) : ((FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) option =
  (let tmp = (FStarC_Syntax_Util.unmeta scrutinee) in
  let tmp1 = (FStarC_Syntax_Util.unlazy tmp) in
  let tmp2 = (FStarC_Syntax_Util.hua tmp1) in
  (match tmp2 with
    | None -> None
    | (Some ((c, tmp3, cargs))) -> (let tmp4 = (FStarC_TypeChecker_Env.is_datacon (cfg).FStarC_TypeChecker_Cfg.tcenv (c).FStarC_Syntax_Syntax.fv_name) in
      let tmp5 = (not tmp4) in
      (if tmp5 then None else (let same = (FStarC_Ident.lid_equals (c).FStarC_Syntax_Syntax.fv_name d) in
      (if is_disc then (Some ((if same then FStarC_Syntax_Util.exp_true_bool else FStarC_Syntax_Util.exp_false_bool))) else (if (not same) then None else (match idx with
        | None -> None
        | (Some (i)) -> (if (Prims.op_Less_Equals (FStarC_List.length cargs) i) then None else (Some ((Custard_FStar_Pervasives_Native.fStar_Pervasives_Native_fst (FStarC_List.nth cargs i)))))
      ))))))
  ))

let head_of_term_is_evaluated (env : FStarC_TypeChecker_Env.env) (t : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) : bool =
  (let tmp = (FStarC_Syntax_Util.head_and_args_full t) in
  (match tmp with
    | (h, tmp1) -> (let tmp2 = (FStarC_Syntax_Util.unlazy h) in
      let tmp3 = (FStarC_Syntax_Util.unmeta tmp2) in
      let h1 = (FStarC_Syntax_Util.un_uinst tmp3) in
      let tmp4 = (FStarC_Syntax_Subst.compress h1) in
      let tmp5 = (tmp4).FStarC_Syntax_Syntax.n in
      (match tmp5 with
        | (FStarC_Syntax_Syntax.Tm_constant (tmp6)) -> true
        | (FStarC_Syntax_Syntax.Tm_fvar (fv)) -> (FStarC_TypeChecker_Env.is_datacon env (fv).FStarC_Syntax_Syntax.fv_name)
        | tmp6 -> false
      ))
  ))

let check_strict_app (cfg : FStarC_TypeChecker_Cfg.cfg) (hua : (FStarC_Syntax_Syntax.fv * (FStarC_Syntax_Syntax.universe) list * (((FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax * (FStarC_Syntax_Syntax.arg_qualifier) option)) list)) : bool =
  (match hua with
    | (h, u, a) -> (let tmp = (FStarC_TypeChecker_Env.fv_has_strict_args (cfg).FStarC_TypeChecker_Cfg.tcenv h) in
      (match tmp with
        | None -> false
        | (Some (strict_indices)) -> ((FStarC_TypeChecker_Cfg.log cfg (fun tmp1 -> (let tmp2 = (FStarC_Syntax_Print.fStarC_Class_Show_show__tuple3_fv_list_universe_list_tuple2 hua) in
          let tmp3 = (FStarC_Syntax_Syntax.fStarC_Class_Show_show__fv h) in
          let tmp4 = (FStarC_Class_Show.fStarC_Class_Show_show__list_int strict_indices) in
          (FStarC_Format.print3 "Checking strict application for %s, head=%s, strict_indices=%s\n" tmp2 tmp3 tmp4))));
          let len_a = (FStarC_List.length a) in
          (FStarC_List.for_all (fun i -> (if (Prims.op_Greater_Equals i len_a) then false else (head_of_term_is_evaluated (cfg).FStarC_TypeChecker_Cfg.tcenv (Custard_FStar_Pervasives_Native.fStar_Pervasives_Native_fst (FStarC_List.nth a i))))) strict_indices))
      ))
  )

let rec check_strict_projector__check (cfg : FStarC_TypeChecker_Cfg.cfg) (args : (((FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax * (FStarC_Syntax_Syntax.arg_qualifier) option)) list) : bool =
  (match args with
    | [] -> false
    | ((last, last_q) :: []) -> (if (match last_q with
        | None -> true
        | tmp -> false
      ) then (head_of_term_is_evaluated (cfg).FStarC_TypeChecker_Cfg.tcenv last) else false)
    | (a :: args') -> (if (match (Custard_FStar_Pervasives_Native.fStar_Pervasives_Native_snd a) with
        | (Some (v)) -> true
        | tmp -> false
      ) then ((check_strict_projector__check cfg) args') else false)
  )

let check_strict_projector (cfg : FStarC_TypeChecker_Cfg.cfg) (hua : (FStarC_Syntax_Syntax.fv * (FStarC_Syntax_Syntax.universe) list * (((FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax * (FStarC_Syntax_Syntax.arg_qualifier) option)) list)) : bool =
  (match hua with
    | (h, u, a) -> (let tmp = (FStarC_TypeChecker_Env.is_projector (cfg).FStarC_TypeChecker_Cfg.tcenv (h).FStarC_Syntax_Syntax.fv_name) in
      let tmp1 = (not tmp) in
      (if tmp1 then false else ((check_strict_projector__check cfg) a)))
  )

let check_strict (cfg : FStarC_TypeChecker_Cfg.cfg) (hua : (FStarC_Syntax_Syntax.fv * (FStarC_Syntax_Syntax.universe) list * (((FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax * (FStarC_Syntax_Syntax.arg_qualifier) option)) list)) : (bool) option =
  (let tmp = (check_strict_app cfg hua) in
  (if tmp then ((FStarC_TypeChecker_Cfg.log cfg (fun tmp1 -> (let tmp2 = (FStarC_Syntax_Print.fStarC_Class_Show_show__tuple3_fv_list_universe_list_tuple2 hua) in
  (FStarC_Format.print1 "Strict application detected for %s\n" tmp2))));
  (Some (false))) else (let tmp1 = (if (((cfg).FStarC_TypeChecker_Cfg.steps).FStarC_TypeChecker_Cfg.reduce_projections && ((cfg).FStarC_TypeChecker_Cfg.steps).FStarC_TypeChecker_Cfg.iota) then (check_strict_projector cfg hua) else false) in
  (if tmp1 then ((FStarC_TypeChecker_Cfg.log cfg (fun tmp2 -> (let tmp3 = (FStarC_Syntax_Print.fStarC_Class_Show_show__tuple3_fv_list_universe_list_tuple2 hua) in
  (FStarC_Format.print1 "Strict projector detected for %s\n" tmp3))));
  (Some (true))) else None))))

let empty_env : (((FStarC_Syntax_Syntax.binder) option * closure * (((FStarC_Syntax_Syntax.subst_elt) list) option ref))) list =
  []

let should_consider_norm_requests (cfg : FStarC_TypeChecker_Cfg.cfg) : bool =
