                let tmp3 = (FStarC_List.map (fun tmp3 -> (dummy ())) xs1) in
                let env1 = (FStarC_List.op_At tmp3 rec_env) in
                let def_body1 = (norm cfg env1 [] def_body) in
                let lopt1 = (match lopt with
                    | (Some (rc)) -> (let tmp4 = (FStarC_Option.map (norm cfg env1 []) (rc).FStarC_Syntax_Syntax.residual_typ) in
                      let tmp5 = { FStarC_Syntax_Syntax.residual_effect = (rc).FStarC_Syntax_Syntax.residual_effect;
                          residual_typ = tmp4;
                          residual_flags = (rc).FStarC_Syntax_Syntax.residual_flags } in
                      (Some (tmp5)))
                    | tmp4 -> lopt
                  ) in
                let def = (FStarC_Syntax_Util.abs xs1 def_body1 lopt1) in
                { FStarC_Syntax_Syntax.lbname = lbname;
                  lbunivs = (lb).FStarC_Syntax_Syntax.lbunivs;
                  lbtyp = ty;
                  lbeff = (lb).FStarC_Syntax_Syntax.lbeff;
                  lbdef = def;
                  lbattrs = (lb).FStarC_Syntax_Syntax.lbattrs;
                  lbpos = (lb).FStarC_Syntax_Syntax.lbpos })
            ))) lbs1) in
          let tmp1 = (FStarC_List.map (fun tmp1 -> (dummy ())) lbs2) in
          let env' = (FStarC_List.op_At tmp1 env) in
          let body2 = (norm cfg env' [] body1) in
          let tmp2 = (FStarC_Syntax_Subst.close_let_rec lbs2 body2) in
          (match tmp2 with
            | (lbs3, body3) -> (let t2 = { FStarC_Syntax_Syntax.n = (FStarC_Syntax_Syntax.Tm_let (({ FStarC_Syntax_Syntax.lbs = true; lbs1 = lbs3; body = body3 } : FStarC_Syntax_Syntax.term'__Tm_let__payload)));
                  pos = (t1).FStarC_Syntax_Syntax.pos;
                  hash_code = (t1).FStarC_Syntax_Syntax.hash_code } in
              (rebuild cfg env stack1 t2))
          ))
      ))
    | (FStarC_Syntax_Syntax.Tm_let ({ FStarC_Syntax_Syntax.lbs = u__1; lbs1 = u__2; body = body; _ })) when ((not ((cfg).FStarC_TypeChecker_Cfg.steps).FStarC_TypeChecker_Cfg.zeta) && (not ((cfg).FStarC_TypeChecker_Cfg.steps).FStarC_TypeChecker_Cfg.zeta_full)) -> (let tmp = (closure_as_term cfg env t1) in
      (rebuild cfg env stack1 tmp))
    | (FStarC_Syntax_Syntax.Tm_let ({ FStarC_Syntax_Syntax.lbs = u__1; lbs1 = u__2; body = body; _ })) -> (let lbs = (u__1, u__2) in
      let tmp = (FStarC_List.fold_right (fun lb tmp -> (match tmp with
          | (env_elts, memos, i) -> (let tmp1 = (match (lb).FStarC_Syntax_Syntax.lbname with
                | (FStar_Pervasives.Inl (v)) -> v
              ) in
            let bv = { FStarC_Syntax_Syntax.ppname = (tmp1).FStarC_Syntax_Syntax.ppname;
                index = i;
                sort = (tmp1).FStarC_Syntax_Syntax.sort } in
            let f_i = (FStarC_Syntax_Syntax.bv_to_tm bv) in
            let fix_f_i = (FStarC_Syntax_Syntax.mk (FStarC_Syntax_Syntax.Tm_let (({ FStarC_Syntax_Syntax.lbs = (match lbs with (custard_tup, _) -> custard_tup);
                lbs1 = (match lbs with (_, custard_tup) -> custard_tup);
                body = f_i } : FStarC_Syntax_Syntax.term'__Tm_let__payload))) (t1).FStarC_Syntax_Syntax.pos) in
            let memo = (fresh_cfg_memo ()) in
            let tmp2 = (fresh_memo ()) in
            let tmp3 = (None, (Clos (env, fix_f_i, memo, true)), tmp2) in
            let env_elts1 = (tmp3 :: env_elts) in
            (env_elts1, (memo :: memos), (Prims.op_Plus i (Prims.parse_int "1"))))
        )) (Custard_FStar_Pervasives_Native.fStar_Pervasives_Native_snd lbs) ([], [], (Prims.parse_int "0"))) in
      (match tmp with
        | (env_elts, memos, tmp1) -> (let rec_env = (FStarC_List.op_At (FStarC_List.rev env_elts) env) in
          (ignore (FStarC_List.map2 (fun lb memo -> (((memo_cell cfg memo)) := (Some ((cfg, (rec_env, (lb).FStarC_Syntax_Syntax.lbdef)))))) (Custard_FStar_Pervasives_Native.fStar_Pervasives_Native_snd lbs) memos));
          let body_env = (FStarC_List.fold_left (fun env1 lb -> (let tmp2 = (fresh_cfg_memo ()) in
            let tmp3 = (rec_env, (lb).FStarC_Syntax_Syntax.lbdef, tmp2, false) in
            let tmp4 = (Clos ((match tmp3 with (custard_tup, _, _, _) -> custard_tup), (match tmp3 with (_, custard_tup, _, _) -> custard_tup), (match tmp3 with (_, _, custard_tup, _) -> custard_tup), (match tmp3 with (_, _, _, custard_tup) -> custard_tup))) in
            let tmp5 = (fresh_memo ()) in
            let tmp6 = (None, tmp4, tmp5) in
            (tmp6 :: env1))) env (Custard_FStar_Pervasives_Native.fStar_Pervasives_Native_snd lbs)) in
          (FStarC_TypeChecker_Cfg.log cfg (fun tmp2 -> (FStarC_Format.print1 "reducing with knot %s\n" "")));
          (norm cfg body_env stack1 body))
      ))
    | (FStarC_Syntax_Syntax.Tm_meta ({ FStarC_Syntax_Syntax.tm = head; meta = m; _ })) -> ((FStarC_TypeChecker_Cfg.log cfg (fun tmp -> (let tmp1 = (FStarC_Syntax_Print.fStarC_Class_Show_show__metadata m) in
      (FStarC_Format.print1 ">> metadata = %s\n" tmp1))));
      (match m with
        | (FStarC_Syntax_Syntax.Meta_monadic (m_from, ty)) -> (if ((cfg).FStarC_TypeChecker_Cfg.steps).FStarC_TypeChecker_Cfg.for_extraction then (let tmp = (FStarC_TypeChecker_Env.is_erasable_effect (cfg).FStarC_TypeChecker_Cfg.tcenv m_from) in
          let tmp1 = (if tmp then true else (if (FStarC_Syntax_Util.is_pure_effect m_from) then (FStarC_TypeChecker_Env.non_informative (cfg).FStarC_TypeChecker_Cfg.tcenv ty) else false)) in
          (if tmp1 then (let tmp2 = (FStarC_Syntax_Syntax.mk (FStarC_Syntax_Syntax.Tm_meta (({ FStarC_Syntax_Syntax.tm = FStarC_Syntax_Util.exp_unit; meta = m } : FStarC_Syntax_Syntax.term'__Tm_meta__payload))) (t1).FStarC_Syntax_Syntax.pos) in
          (rebuild cfg env stack1 tmp2)) else (reduce_impure_comp cfg env stack1 head (FStar_Pervasives.Inl (m_from)) ty))) else (reduce_impure_comp cfg env stack1 head (FStar_Pervasives.Inl (m_from)) ty))
        | (FStarC_Syntax_Syntax.Meta_monadic_lift (m_from, m_to, ty)) -> (if ((cfg).FStarC_TypeChecker_Cfg.steps).FStarC_TypeChecker_Cfg.for_extraction then (let tmp = (FStarC_TypeChecker_Env.is_erasable_effect (cfg).FStarC_TypeChecker_Cfg.tcenv m_from) in
          let tmp1 = (if tmp then true else (FStarC_TypeChecker_Env.is_erasable_effect (cfg).FStarC_TypeChecker_Cfg.tcenv m_to)) in
          let tmp2 = (if tmp1 then true else (if (FStarC_Syntax_Util.is_pure_effect m_from) then (FStarC_TypeChecker_Env.non_informative (cfg).FStarC_TypeChecker_Cfg.tcenv ty) else false)) in
          (if tmp2 then (let tmp3 = (FStarC_Syntax_Syntax.mk (FStarC_Syntax_Syntax.Tm_meta (({ FStarC_Syntax_Syntax.tm = FStarC_Syntax_Util.exp_unit; meta = m } : FStarC_Syntax_Syntax.term'__Tm_meta__payload))) (t1).FStarC_Syntax_Syntax.pos) in
          (rebuild cfg env stack1 tmp3)) else (reduce_impure_comp cfg env stack1 head (FStar_Pervasives.Inr ((m_from, m_to))) ty))) else (reduce_impure_comp cfg env stack1 head (FStar_Pervasives.Inr ((m_from, m_to))) ty))
        | tmp -> (if ((cfg).FStarC_TypeChecker_Cfg.steps).FStarC_TypeChecker_Cfg.unmeta then (norm cfg env stack1 head) else (match stack1 with
            | (tmp1 :: tmp2) -> (match m with
                | (FStarC_Syntax_Syntax.Meta_labeled (l, r, tmp3)) -> (norm cfg env ((Meta (env, m, r)) :: stack1) head)
                | (FStarC_Syntax_Syntax.Meta_pattern (names, args)) -> (let args1 = (norm_pattern_args cfg env args) in
                  let names1 = (FStarC_List.map (norm cfg env []) names) in
                  (norm cfg env ((Meta (env, (FStarC_Syntax_Syntax.Meta_pattern (names1, args1)), (t1).FStarC_Syntax_Syntax.pos)) :: stack1) head))
                | (FStarC_Syntax_Syntax.Meta_desugared (FStarC_Syntax_Syntax.Sequence)) when ((cfg).FStarC_TypeChecker_Cfg.steps).FStarC_TypeChecker_Cfg.do_not_unfold_pure_lets -> (norm cfg env ((Meta (env, m, (t1).FStarC_Syntax_Syntax.pos)) :: stack1) head)
                | (FStarC_Syntax_Syntax.Meta_desugared ((FStarC_Syntax_Syntax.Machine_integer (tmp3, tmp4)))) -> (norm cfg env ((Meta (env, m, (t1).FStarC_Syntax_Syntax.pos)) :: stack1) head)
                | tmp3 -> (norm cfg env stack1 head)
              )
            | [] -> (let head1 = (norm cfg env [] head) in
              let m1 = (match m with
                  | (FStarC_Syntax_Syntax.Meta_pattern (names, args)) -> (let names1 = (FStarC_List.map (norm cfg env []) names) in
                    let tmp1 = (norm_pattern_args cfg env args) in
                    let tmp2 = (names1, tmp1) in
                    (FStarC_Syntax_Syntax.Meta_pattern ((match tmp2 with (custard_tup, _) -> custard_tup), (match tmp2 with (_, custard_tup) -> custard_tup))))
                  | tmp1 -> m
                ) in
              let t2 = (FStarC_Syntax_Syntax.mk (FStarC_Syntax_Syntax.Tm_meta (({ FStarC_Syntax_Syntax.tm = head1; meta = m1 } : FStarC_Syntax_Syntax.term'__Tm_meta__payload))) (t1).FStarC_Syntax_Syntax.pos) in
              (rebuild cfg env stack1 t2))
          ))
      ))
    | (FStarC_Syntax_Syntax.Tm_delayed (tmp)) -> (FStarC_Effect.failwith "impossible: Tm_delayed on norm")
    | (FStarC_Syntax_Syntax.Tm_uvar (u__1, u__2)) -> ((if ((cfg).FStarC_TypeChecker_Cfg.steps).FStarC_TypeChecker_Cfg.check_no_uvars then (let tmp = (FStarC_Range_Ops.fStarC_Class_Show_show__range (t1).FStarC_Syntax_Syntax.pos) in
      let tmp1 = (FStarC_Syntax_Print.fStarC_Class_Show_show__syntax_term' t1) in
      let tmp2 = (FStarC_Format.fmt2 "(%s) CheckNoUvars: Unexpected unification variable remains: %s" tmp tmp1) in
      (FStarC_Effect.failwith tmp2)) else ());
      let t2 = (FStarC_Errors.with_ctx "inlining" (fun tmp -> (closure_as_term cfg env t1))) in
      (rebuild cfg env stack1 t2))
