let normalize_with_primitive_steps (ps : (FStarC_TypeChecker_Primops_Base.primitive_step) list) (s : (FStarC_TypeChecker_Env.step) list) (e : FStarC_TypeChecker_Env.env) (t : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax =
  (FStarC_Stats.record "norm_term" (fun tmp -> (let is_nbe = (is_nbe_request s) in
  let maybe_nbe = (if is_nbe then " (NBE)" else "") in
  (FStarC_Errors.with_ctx (Prims.strcat "While normalizing a term" maybe_nbe) (fun tmp1 -> (FStarC_Profiling.profile (fun tmp2 -> (let c = (FStarC_TypeChecker_Cfg.config' ps s e) in
  ((reflection_env_hook) := (Some (e)));
  ((plugin_unfold_warn_ctr) := (Prims.parse_int "1"));
  (FStarC_TypeChecker_Cfg.log_top c (fun tmp3 -> (let tmp4 = (FStarC_Syntax_Print.fStarC_Class_Show_show__syntax_term' t) in
  (FStarC_Format.print2 "\nStarting normalizer%s for (%s) {\n" maybe_nbe tmp4))));
  (FStarC_TypeChecker_Cfg.log_top c (fun tmp3 -> (let tmp4 = (FStarC_TypeChecker_Cfg.fStarC_Class_Show_show__cfg c) in
  (FStarC_Format.print1 ">>> cfg = %s\n" tmp4))));
  (FStarC_TypeChecker_Env.fStarC_Defensive_def_check_scoped__env_syntax_term' (t).FStarC_Syntax_Syntax.pos "normalize_with_primitive_steps call" e t);
  let tmp3 = (FStarC_Timing.record_ms (fun tmp3 -> (if is_nbe then (nbe_eval c s t) else (norm c [] [] t)))) in
  (match tmp3 with
    | (r, ms) -> ((FStarC_TypeChecker_Cfg.log_top c (fun tmp4 -> (let tmp5 = (FStarC_Syntax_Print.fStarC_Class_Show_show__syntax_term' r) in
      let tmp6 = (FStarC_Class_Show.fStarC_Class_Show_show__int ms) in
      (FStarC_Format.print3 "}\nNormalization%s result = (%s) in %s ms\n" maybe_nbe tmp5 tmp6))));
      r)
  ))) (Some ((FStarC_Ident.string_of_lid (FStarC_TypeChecker_Env.current_module e)))) "FStarC.TypeChecker.Normalize.normalize_with_primitive_steps"))))))

let normalize (s : (FStarC_TypeChecker_Env.step) list) (e : FStarC_TypeChecker_Env.env) (t : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax =
  (FStarC_Profiling.profile (fun tmp -> (normalize_with_primitive_steps [] s e t)) (Some ((FStarC_Ident.string_of_lid (FStarC_TypeChecker_Env.current_module e)))) "FStarC.TypeChecker.Normalize.normalize")

let whnf_steps : (FStarC_TypeChecker_Env.step) list =
  (FStarC_TypeChecker_Env.Primops :: (FStarC_TypeChecker_Env.Weak :: (FStarC_TypeChecker_Env.HNF :: ((FStarC_TypeChecker_Env.UnfoldUntil (FStarC_Syntax_Syntax.delta_constant)) :: (FStarC_TypeChecker_Env.Beta :: [])))))

let unfold_whnf' (steps : (FStarC_TypeChecker_Env.step) list) (e : FStarC_TypeChecker_Env.env) (t : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax =
  (normalize (FStarC_List.op_At steps whnf_steps) e t)

let for_printing_steps : (FStarC_TypeChecker_Env.step) list =
  (FStarC_TypeChecker_Env.AllowUnboundUniverses :: ((FStarC_TypeChecker_Env.Exclude (FStarC_TypeChecker_Env.Zeta)) :: []))

let warn_norm_failure (r : FStarC_Range_Type.range) (e : exn) : unit =
  (let tmp = (FStarC_Util.message_of_exn e) in
  let tmp1 = (FStarC_Format.fmt1 "Normalization failed with error %s\n" tmp) in
  (FStarC_Errors.fStarC_Errors_log_issue__range_string r FStarC_Errors_Codes.Warning_NormalizationFailure tmp1))

let comp_to_string (env : FStarC_TypeChecker_Env.env) (c : (FStarC_Syntax_Syntax.comp_typ) FStarC_Syntax_Syntax.syntax) : string =
  (FStarC_GenSym.with_frozen_gensym (fun tmp -> (let c1 = (try (let tmp1 = (FStarC_TypeChecker_Cfg.config for_printing_steps env) in
    (norm_comp tmp1 [] c)) with
      | u__cexn -> ((warn_norm_failure (c).FStarC_Syntax_Syntax.pos u__cexn);
        c)
    ) in
  (FStarC_Syntax_Print.comp_to_string' (FStarC_Syntax_DsEnv.set_current_module (env).FStarC_TypeChecker_Env.dsenv (env).FStarC_TypeChecker_Env.curmodule) c1))))

let term_to_string (env : FStarC_TypeChecker_Env.env) (t : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) : string =
  (FStarC_GenSym.with_frozen_gensym (fun tmp -> (let t1 = (try (normalize for_printing_steps env t) with
      | u__cexn -> ((warn_norm_failure (t).FStarC_Syntax_Syntax.pos u__cexn);
        t)
    ) in
  (FStarC_Syntax_Print.term_to_string' (FStarC_Syntax_DsEnv.set_current_module (env).FStarC_TypeChecker_Env.dsenv (env).FStarC_TypeChecker_Env.curmodule) t1))))

let normalize_universe (env : FStarC_TypeChecker_Env.env) (u : FStarC_Syntax_Syntax.universe) : FStarC_Syntax_Syntax.universe =
  (FStarC_Errors.with_ctx "While normalizing a universe level" (fun tmp -> (let tmp1 = (FStarC_TypeChecker_Cfg.config [] env) in
  (norm_universe tmp1 [] u))))

let reduce_or_remove_uvar_solutions (remove : bool) : (FStarC_TypeChecker_Env.env -> ((FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax -> (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax)) =
  (normalize (FStarC_List.op_At (if remove then (FStarC_TypeChecker_Env.DefaultUnivsToZero :: (FStarC_TypeChecker_Env.CheckNoUvars :: [])) else []) (FStarC_TypeChecker_Env.Beta :: (FStarC_TypeChecker_Env.DoNotUnfoldPureLets :: (FStarC_TypeChecker_Env.CompressUvars :: ((FStarC_TypeChecker_Env.Exclude (FStarC_TypeChecker_Env.Zeta)) :: ((FStarC_TypeChecker_Env.Exclude (FStarC_TypeChecker_Env.Iota)) :: (FStarC_TypeChecker_Env.NoFullNorm :: []))))))))

let reduce_uvar_solutions (env : FStarC_TypeChecker_Env.env) : ((FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax -> (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) =
  (reduce_or_remove_uvar_solutions false env)

let unfold_whnf (env : FStarC_TypeChecker_Env.env) (t : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax =
  (unfold_whnf' [] env t)

let term_to_doc (env : FStarC_TypeChecker_Env.env) (t : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) : FStar_Pprint.document =
  (let t1 = (try (normalize for_printing_steps env t) with
      | u__cexn -> ((warn_norm_failure (t).FStarC_Syntax_Syntax.pos u__cexn);
        t)
    ) in
  let env' = (FStarC_Syntax_DsEnv.set_current_module (env).FStarC_TypeChecker_Env.dsenv (env).FStarC_TypeChecker_Env.curmodule) in
  let tmp = (FStarC_Options.interactive ()) in
  let env'1 = (if tmp then env' else (FStarC_Syntax_DsEnv.clear_scope_mods env')) in
  (FStarC_Syntax_Print.term_to_doc' env'1 t1))

let non_info_norm (env : FStarC_TypeChecker_Env.env) (t : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) : bool =
  (let steps = ((FStarC_TypeChecker_Env.UnfoldUntil (FStarC_Syntax_Syntax.delta_constant)) :: (FStarC_TypeChecker_Env.AllowUnboundUniverses :: (FStarC_TypeChecker_Env.EraseUniverses :: (FStarC_TypeChecker_Env.Primops :: (FStarC_TypeChecker_Env.Beta :: (FStarC_TypeChecker_Env.Iota :: (FStarC_TypeChecker_Env.HNF :: (FStarC_TypeChecker_Env.Unascribe :: (FStarC_TypeChecker_Env.ForExtraction :: []))))))))) in
  let tmp = (normalize steps env t) in
  (FStarC_TypeChecker_Env.non_informative env tmp))

let maybe_promote_t (env : FStarC_TypeChecker_Env.env) (non_informative_only : bool) (t : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) : bool =
  (if (not non_informative_only) then true else (non_info_norm env t))

let downgrade_ghost_effect_name (l : FStarC_Ident.lident) : (FStarC_Ident.lident) option =
  (if (FStarC_Parser_Const.is_ghost_effect_lid l) then (Some (FStarC_Parser_Const.primitive_pure_lid)) else None)

let ghost_to_pure_aux (env : FStarC_TypeChecker_Env.env) (non_informative_only : bool) (c : (FStarC_Syntax_Syntax.comp_typ) FStarC_Syntax_Syntax.syntax) : (FStarC_Syntax_Syntax.comp_typ) FStarC_Syntax_Syntax.syntax =
  (match (c).FStarC_Syntax_Syntax.n with
    | ct -> (let l = (ct).FStarC_Syntax_Syntax.effect_name in
      let tmp = (if (FStarC_Syntax_Util.is_ghost_effect l) then (maybe_promote_t env non_informative_only (ct).FStarC_Syntax_Syntax.result_typ) else false) in
      (if tmp then (let ct1 = (match (downgrade_ghost_effect_name (ct).FStarC_Syntax_Syntax.effect_name) with
          | (Some (pure_eff)) -> { FStarC_Syntax_Syntax.effect_name = pure_eff;
              result_typ = (ct).FStarC_Syntax_Syntax.result_typ;
              flags = (ct).FStarC_Syntax_Syntax.flags;
              source_effect_name = pure_eff }
          | None -> (let ct1 = (FStarC_Syntax_Util.comp_to_comp_typ c) in
            { FStarC_Syntax_Syntax.effect_name = FStarC_Parser_Const.primitive_pure_lid;
              result_typ = (ct1).FStarC_Syntax_Syntax.result_typ;
              flags = (ct1).FStarC_Syntax_Syntax.flags;
              source_effect_name = FStarC_Parser_Const.primitive_pure_lid })
        ) in
      { FStarC_Syntax_Syntax.n = ct1;
        pos = (c).FStarC_Syntax_Syntax.pos;
        hash_code = (c).FStarC_Syntax_Syntax.hash_code }) else c))
    | tmp -> c
  )

let maybe_ghost_to_pure (env : FStarC_TypeChecker_Env.env) (c : (FStarC_Syntax_Syntax.comp_typ) FStarC_Syntax_Syntax.syntax) : (FStarC_Syntax_Syntax.comp_typ) FStarC_Syntax_Syntax.syntax =
  (ghost_to_pure_aux env true c)

let ghost_to_pure (env : FStarC_TypeChecker_Env.env) (c : (FStarC_Syntax_Syntax.comp_typ) FStarC_Syntax_Syntax.syntax) : (FStarC_Syntax_Syntax.comp_typ) FStarC_Syntax_Syntax.syntax =
  (ghost_to_pure_aux env false c)

let ghost_to_pure2 (env : FStarC_TypeChecker_Env.env) (tmp : ((FStarC_Syntax_Syntax.comp_typ) FStarC_Syntax_Syntax.syntax * (FStarC_Syntax_Syntax.comp_typ) FStarC_Syntax_Syntax.syntax)) : ((FStarC_Syntax_Syntax.comp_typ) FStarC_Syntax_Syntax.syntax * (FStarC_Syntax_Syntax.comp_typ) FStarC_Syntax_Syntax.syntax) =
  (match tmp with
    | (c1, c2) -> (let tmp1 = (maybe_ghost_to_pure env c1) in
      let tmp2 = (maybe_ghost_to_pure env c2) in
      let tmp3 = (tmp1, tmp2) in
      (match tmp3 with
        | (c11, c21) -> (let c1_eff = (FStarC_Syntax_Util.comp_effect_name c11) in
          let c2_eff = (FStarC_Syntax_Util.comp_effect_name c21) in
          (if (FStarC_Ident.lid_equals c1_eff c2_eff) then (c11, c21) else (let c1_erasable = (FStarC_TypeChecker_Env.is_erasable_effect env c1_eff) in
          let c2_erasable = (FStarC_TypeChecker_Env.is_erasable_effect env c2_eff) in
          (if (c1_erasable && (FStarC_Parser_Const.is_ghost_effect_lid c2_eff)) then (let tmp4 = (ghost_to_pure env c21) in
          (c11, tmp4)) else (if (c2_erasable && (FStarC_Parser_Const.is_ghost_effect_lid c1_eff)) then (let tmp4 = (ghost_to_pure env c11) in
          (tmp4, c21)) else (c11, c21))))))
      ))
  )

let normalize_refinement (steps : (FStarC_TypeChecker_Env.step) list) (env : FStarC_TypeChecker_Env.env) (t0 : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax =
  (let t = (normalize (FStarC_List.op_At steps (FStarC_TypeChecker_Env.Beta :: [])) env t0) in
  (FStarC_Syntax_Util.flatten_refinement t))

let normalize_comp (s : (FStarC_TypeChecker_Env.step) list) (e : FStarC_TypeChecker_Env.env) (c : (FStarC_Syntax_Syntax.comp_typ) FStarC_Syntax_Syntax.syntax) : (FStarC_Syntax_Syntax.comp_typ) FStarC_Syntax_Syntax.syntax =
  (FStarC_Stats.record "norm_comp" (fun tmp -> (FStarC_Profiling.profile (fun tmp1 -> (let cfg = (FStarC_TypeChecker_Cfg.config s e) in
  ((reflection_env_hook) := (Some (e)));
