        (if tmp1 then (let tmp2 = (FStarC_Syntax_Util.has_decreases c1) in
        (not tmp2)) else false)) -> (let tmp1 = ((get_n_binders_gen__aux split env steps) true (Prims.op_Minus n len) (FStarC_Syntax_Util.comp_result c1)) in
          (match tmp1 with
