let elim_uvars_aux_tc (env : FStarC_TypeChecker_Env.env) (univ_names : (FStarC_Ident.ident) list) (binders : (FStarC_Syntax_Syntax.binder) list) (tc : ((FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax, (FStarC_Syntax_Syntax.comp_typ) FStarC_Syntax_Syntax.syntax) FStar_Pervasives.either) : ((FStarC_Ident.ident) list * (FStarC_Syntax_Syntax.binder) list * ((FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax, (FStarC_Syntax_Syntax.comp_typ) FStarC_Syntax_Syntax.syntax) FStar_Pervasives.either) =
  (let t = (match (binders, tc) with
